{"policy":"permit (
    principal is Person,
    action == Action::"approveOffer",
    resource is Offer
)
when {
    principal.roles.contains(Role::"hiringManager")
};

forbid (
    principal is Person,
    action == Action::"approveOffer",
    resource is Offer
)
when {
    principal.roles.contains(Role::"hiringManager") &&
    resource.status != "drafted" &&
    !context.isWithinPermittedWindow
};"}
